body:
We probably need a second pass to make it work:
- shape with absolute min. width
- resize to actual width

```diff
diff --git a/scene/gui/rich_text_label.cpp b/scene/gui/rich_text_label.cpp
index 27e2f94dee..6fd957532b 100644
--- a/scene/gui/rich_text_label.cpp
+++ b/scene/gui/rich_text_label.cpp
@@ -635,8 +635,7 @@ float RichTextLabel::_shape_line(ItemFrame *p_frame, int p_line, const Ref<Font>
                                                MutexLock sub_lock(frame->lines[i].text_buf->get_mutex());

                                                int char_offset = l.char_offset + l.char_count;
-                                               int w = base_column_width - frame->padding.position.x - frame->padding.size.x;
-                                               w = MAX(w, _find_margin(frame->lines[i].from, p_base_font, p_base_font_size) + 1);
+                                               int w = _find_margin(frame->lines[i].from, p_base_font, p_base_font_size) + 1;
                                                prev_h = _shape_line(frame, i, p_base_font, p_base_font_size, w, prev_h, &char_offset);
                                                int cell_ch = (char_offset - (l.char_offset + l.char_count));
                                                l.char_count += cell_ch;
@@ -648,6 +647,17 @@ float RichTextLabel::_shape_line(ItemFrame *p_frame, int p_line, const Ref<Font>
                                        }
                                        idx++;
                                }
+                               for (Item *E : table->subitems) {
+                                       ERR_CONTINUE(E->type != ITEM_FRAME); // Children should all be frames.
+                                       ItemFrame *frame = static_cast<ItemFrame *>(E);
+
+                                       float prev_h = 0;
+                                       for (int i = 0; i < (int)frame->lines.size(); i++) {
+                                               int w = base_column_width - frame->padding.position.x - frame->padding.size.x;
+                                               w = MAX(w, _find_margin(frame->lines[i].from, p_base_font, p_base_font_size) + 1);
+                                               prev_h = _resize_line(frame, i, p_base_font, p_base_font_size, w, prev_h);
+                                       }
+                               }

                                _set_table_size(table, available_width);
```

But this should be performance tested with large tables (e.g., engine docs), if it's adding segnificant time to the initial shaping, so extra condition can be added to only call resize if nested tables were found during `_shape_line`.
